"""SCMOVS update: new Super Admin dashboard, new user table, and a responsive layout for the whole system.

WHAT CHANGES
  Super Admin dashboard
    * The Projects, Events, Approved Expenses and Available Balance cards are replaced by a "Department Statistics" panel
      (per department: status, eligible voters, votes cast, participation rate and a progress bar; real database numbers).
    * The four old graphs are replaced by two:  a LINE graph "Budget and Expenses Monitoring" (approved budgets and approved
      expenses per month, in pesos) and a VERTICAL BAR graph "Open Election Voting Participation" (voted vs. not yet voted
      per open election). Both handle "no data" without errors.
    * Recent actions and Recent logins are untouched.
  User Management table
    * Columns are now: Name & Email | Username / ID | Role | Status | Actions.  The name is shown as
      LASTNAME, FIRST MIDDLE with the email under it. The Last Login column is gone.
  Whole system
    * Tables turn into labelled cards on phones (nothing hidden, no sideways scrolling); pages no longer stretch sideways on
      tablets; modals fit phone screens; charts resize when the sidebar opens or collapses.
  BUG FIX
    * The shared chart code crashed Chart.js ("Maximum call stack size exceeded") on the dashboards, so only the first chart
      on a page was drawn. That is fixed.

NO database change is needed.

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_dashboard_update.py
  3. Restart the app (python run.py) and press Ctrl+F5 in the browser.

Your current copy of every file it replaces is saved first in _update_backup/ (same sub-folders).
"""
import base64
import os
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FILES = {
    'app/__init__.py': "",
    'app/admin/services.py': "",
    'app/validators.py': "",
    'static/css/dark.css': "",
    'static/js/charts_common.js': "",
    'static/js/modal.js': "",
    'static/js/responsive_tables.js': "",
    'static/js/super_admin_dashboard.js': "",
    'templates/base.html': "",
    'templates/layouts/app_layout.html': "",
    'templates/super_admin/dashboard.html': "",
    'templates/super_admin/users/list.html': "",
    'tests/run_all.sh': "",
    'tests/test_dashboard_redesign.py': "",
    'tests/test_phase3_4.py': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put this file in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    if not os.path.isfile(os.path.join(ROOT, "app", "locations.py")):
        print("STOP: this update builds on the earlier ones. Apply apply_big_update.py first (and the others after it).")
        sys.exit(1)
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(ROOT, "_update_backup", *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        print("  updated", rel)
    print(f"\n{len(FILES)} files written. Restart the app (python run.py) and press Ctrl+F5 in the browser.")


if __name__ == "__main__":
    main()
